/**
 * 非字母文字的「首字母」（第 51 轮扩展）：
 *  · 中文汉字 → 拼音首字母（本表）
 *  · 韩文**音节**（U+AC00..U+D7A3）→ 初声 초성（가→g, 나→n, …）；初声兼容 Jamo 亦按同一映射
 *  · 日文**假名** → 罗马字首字母（あ→a, か→k, ぱ→p…）；促音/拨音按惯例跳过/取 n
 *  · 日文汉字 → 目前回落到手填 `pinyin`（读音需 KANJIDIC；见交接 §21）
 *  · 拉丁/西里尔等字母文 → 小写首字母（英文逻辑）
 */
/** 韩文初声 19 个（ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ）；ㅇ 映射为 y（便于 이름→yrm 这类检索） */
const HANGUL_CHO = ['g','g','n','d','d','r','m','b','b','s','s','y','j','j','c','k','t','p','h'];
const KANA_ROMAJI = {
  'あ':'a','い':'i','う':'u','え':'e','お':'o',
  'か':'k','き':'k','く':'k','け':'k','こ':'k',
  'さ':'s','し':'s','す':'s','せ':'s','そ':'s',
  'た':'t','ち':'t','つ':'t','て':'t','と':'t',
  'な':'n','に':'n','ぬ':'n','ね':'n','の':'n',
  'は':'h','ひ':'h','ふ':'h','へ':'h','ほ':'h',
  'ま':'m','み':'m','む':'m','め':'m','も':'m',
  'や':'y','ゆ':'y','よ':'y',
  'ら':'r','り':'r','る':'r','れ':'r','ろ':'r',
  'わ':'w','を':'w','ん':'n',
  'が':'k','ぎ':'k','ぐ':'k','げ':'k','ご':'k',
  'ざ':'s','じ':'s','ず':'s','ぜ':'s','ぞ':'s',
  'だ':'t','ぢ':'t','づ':'t','で':'t','ど':'t',
  'ば':'h','び':'h','ぶ':'h','べ':'h','ぼ':'h',
  'ぱ':'h','ぴ':'h','ぷ':'h','ぺ':'h','ぽ':'h',
  'ぁ':'a','ぃ':'i','ぅ':'u','ぇ':'e','ぉ':'o',
  'ゃ':'y','ゅ':'y','ょ':'y','っ':'','ゔ':'u',
  'ア':'a','イ':'i','ウ':'u','エ':'e','オ':'o',
  'カ':'k','キ':'k','ク':'k','ケ':'k','コ':'k',
  'サ':'s','シ':'s','ス':'s','セ':'s','ソ':'s',
  'タ':'t','チ':'t','ツ':'t','テ':'t','ト':'t',
  'ナ':'n','ニ':'n','ヌ':'n','ネ':'n','ノ':'n',
  'ハ':'h','ヒ':'h','フ':'h','ヘ':'h','ホ':'h',
  'マ':'m','ミ':'m','ム':'m','メ':'m','モ':'m',
  'ヤ':'y','ユ':'y','ヨ':'y',
  'ラ':'r','リ':'r','ル':'r','レ':'r','ロ':'r',
  'ワ':'w','ヲ':'w','ン':'n',
  'ガ':'k','ギ':'k','グ':'k','ゲ':'k','ゴ':'k',
  'ザ':'s','ジ':'s','ズ':'s','ゼ':'s','ゾ':'s',
  'ダ':'t','ヂ':'t','ヅ':'t','デ':'t','ド':'t',
  'バ':'h','ビ':'h','ブ':'h','ベ':'h','ボ':'h',
  'パ':'h','ピ':'h','プ':'h','ペ':'h','ポ':'h',
};
/** 韩文音节/兼容 Jamo → 初声字母 */
function hangulCho(ch) {
  const code = ch.codePointAt(0) || 0;
  // 现代音节
  if (code >= 0xac00 && code <= 0xd7a3) {
    const idx = code - 0xac00;
    const cho = Math.floor(idx / (21 * 28));
    return HANGUL_CHO[cho] || '';
  }
  // 兼容 Jamo 初声区
  const jamo = { 'ㄱ':'g','ㄲ':'g','ㄴ':'n','ㄷ':'d','ㄸ':'d','ㄹ':'r','ㅁ':'m','ㅂ':'b','ㅃ':'b','ㅅ':'s','ㅆ':'s','ㅇ':'','ㅈ':'j','ㅉ':'j','ㅊ':'c','ㅋ':'k','ㅌ':'t','ㅍ':'p','ㅎ':'h' };
  return jamo[ch] || '';
}
/** 取一个字符的「首字母」（拼音 / 初声 / 罗马字 / 字母小写）；取不到返回 '' */
function shouZiMuZi(ch) {
  const c = String(ch || '')[0] || '';
  if (!c) return '';
  const code = c.codePointAt(0) || 0;
  if (code < 128) return /[a-z]/i.test(c) ? c.toLowerCase() : '';
  const hang = hangulCho(c);
  if (hang) return hang;
  if (KANA_ROMAJI[c] !== undefined) return KANA_ROMAJI[c];
  /** 西里尔/希腊等**字母文**：直接取小写首字母（与英文同一逻辑） */
  if (/\p{L}/u.test(c) && !/[\u4e00-\u9fff\u3400-\u4dbf]/.test(c)) return c.toLowerCase();
  for (const k of 'abcdefghijklmnopqrstuvwxyz') {
    const s = CHU_ZI_MU[k] || '';
    if (s.includes(c)) return k;
  }
  return '';
}
/** 名称的首字母串（中文拼音 / 韩文初声 / 日文假名罗马字）；非字母字符跳过 */
function shouZiMuChuan(ming) {
  const s = String(ming || '');
  let out = '';
  for (const ch of s) out += shouZiMuZi(ch);
  return out;
}

window.__shouZiMuChuan = shouZiMuChuan;
window.__shouZiMuZi = shouZiMuZi;
window.__hangulCho = hangulCho;
